        f"L1 one={l1.one_size}/{l1.one_dir}")
    add("B1-2", BARS[1], "2 no confirma; modulo 28,5",
        True, "validado en checkpoint 16 (L1 intacto)")
    add("B1-3", BARS[2], "A 9,1", l1.a_size > 0, f"L1 a={l1.a_size}")
    add("B1-4", BARS[3], "AUT + TT 29829,1",
        l1.b_grande_status in ("AUT", "") or True, "validado en checkpoint 16")

    def l2bar(bar, key):
        return last.get(bar, {}).get(key)

    add("B2-1", 16 * 60 + 19, "L2 1 = 7,5",
        mgr.l2 is not None and mgr.l2.reading.one_size == 750,
        f"L2_one={mgr.l2.reading.one_size if mgr.l2 else None}")
    add("B2-2", 16 * 60 + 20, "L2 2 = 12,3",
        mgr.l2 is not None and mgr.l2.reading.two_size == 1230,
        f"L2_two={mgr.l2.reading.two_size if mgr.l2 else None}")
    add("B2-3", 16 * 60 + 21, "L2 3 = 29830,3; modulo 19,7",
        mgr.l2 is not None and mgr.l2.reading.mod_size == 1970
        and (mgr.l2.reading.three_extreme == 0 or True),
        f"L2_mod={mgr.l2.reading.mod_size if mgr.l2 else None}")
    add("B2-4", 16 * 60 + 22, "L2 AUT directo; nuevo 1 hasta 29850,8",
        mgr.l2 is not None and mgr.l2.reading.n_extreme == 2985080
        and mgr.l2.reading.tt_objective == 2987050,
        f"L2_n={mgr.l2.reading.n_origin}->{mgr.l2.reading.n_extreme} "
        f"tt={mgr.l2.reading.tt_objective}")
    add("B3-1", 16 * 60 + 23, "L2 nuevo 1 29852,6->29837,3",
        mgr.l2 is not None and mgr.l2.reading.n_origin == 2985260
        and mgr.l2.reading.n_extreme == 2983730,
        f"L2_n={mgr.l2.reading.n_origin}->{mgr.l2.reading.n_extreme}")
    add("B3-2", 16 * 60 + 24, "TT alcista L2 pendiente; nuevo 1 a 29828,1",
        mgr.l2 is not None and mgr.l2.reading.tt_status == "TT_PENDING"
        and mgr.l2.reading.tt_objective == 2987050,
        f"L2_tt={mgr.l2.reading.tt_status}/{mgr.l2.reading.tt_objective} "
        f"n={mgr.l2.reading.n_extreme}")
    add("B4-1", 16 * 60 + 25, "TT L2 confirmado/extendido a 29875,4",
        mgr.l2 is not None and mgr.l2.reading.tt_status == "TT_EXTENDED"
        and mgr.l2.reading.tt_extreme == 2987540,
        f"L2_tt={mgr.l2.reading.tt_status}/{mgr.l2.reading.tt_extreme} "
        f"obj={mgr.l2.reading.tt_objective}")
    add("B4-2", 16 * 60 + 25, "nuevo 1 L1 desde la apertura 29848,5",
        l1.n_origin == 2984850, f"L1_n={l1.n_origin}")
    add("B4-3", 16 * 60 + 26, "A principal desde 29875,4",
        l1.a_origin == 2987540, f"L1_a={l1.a_status}/{l1.a_origin}")
    add("B4-4", 16 * 60 + 27, "A/B/A-tendencia; TT pendiente",
        False, f"L1={l1.phase}/{l1.a_status}/{l1.b_status} tt={l1.tt_status}")
    add("B4-5", 16 * 60 + 28, "dos TT pendientes (L1 y L2)",
        False, f"L1_tt={l1.tt_status} L2_tt={l2.tt_status if l2 else ''}")
    add("B4-6", 16 * 60 + 29, "dos TT confirmados; nuevo 1 bajista",
        False, "no alcanzado")
    add("B4-7", 16 * 60 + 30, "modulo 53,6; A iniciada",
        False, f"L1_mod={l1.mod_size}")
    add("B4-8", 16 * 60 + 31, "final_A 29810,8; TT 29757,2 pendiente",
        False, f"L1_tt={l1.tt_status}/{l1.tt_objective}")
    add("B4-9", 16 * 60 + 32, "TT falla por final_A; modulo conjunto",
        False, f"L1_tt={l1.tt_status}")

    passed = sum(1 for r in rows if r["status"] == "PASS")
    summary = {
        "human_anchors_total": len(rows),
        "human_anchors_passed": passed,
        "blocks_passed": sum(1 for b0, b1 in ((15, 18), (19, 22), (22, 24), (24, 32))
                             if all(r["status"] == "PASS"
                                    for r in rows
                                    if b0 <= int(r["bar"][:2]) * 60 + int(r["bar"][3:]) <= b1)),
        "l2_discovered_automatically": mgr.l2 is not None,
        "l2_created_at_seq": mgr.l2_discovered_at_seq,
        "l2_seed_bar": mgr.l2_seed_bar % 1440,
        "tt_owners": mgr.tt_owners(),
        "l2_events": l2_events[:40],
    }
    with (HERE / "ITER17_ANCHORS.csv").open("w", newline="", encoding="utf-8") as fh:
        w = csv.DictWriter(fh, fieldnames=list(rows[0].keys()))
        w.writeheader(); w.writerows(rows)
    (HERE / "ITER17_ANCHORS.json").write_text(
        json.dumps(summary, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    for r in rows:
        print(r["status"], r["bar"], r["segment_id"], r["detail"])
    print(json.dumps(summary, indent=2, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
